-- V6: a private, household-scoped physical cooking ledger. Menu/shopping are read-only inputs.
begin;
grant create on schema app_private to week_menu_executor;
create table app_private.cooking_rules(recipe_id text primary key,data jsonb not null);
revoke all on app_private.cooking_rules from public,anon,authenticated;
grant select on app_private.cooking_rules to week_menu_executor;
insert into app_private.cooking_rules values('b01','{"recipe_id": "b01", "method": [{"id": "main", "instructions": [{"en": "Core and dice the apple; grate the ginger.", "es": "Retira el corazón de la manzana, córtala y ralla el jengibre."}, {"en": "Simmer the oats, milk, apple and ginger gently for 5–8 minutes, stirring; add a little water if needed.", "es": "Cuece suavemente la avena, la leche, la manzana y el jengibre durante 5–8 minutos, removiendo; añade un poco de agua si hace falta."}, {"en": "Serve with the measured chopped walnuts.", "es": "Sirve con las nueces pesadas y troceadas."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "oats", "unit": "g"}, {"ingredient_id": "milk", "unit": "g"}, {"ingredient_id": "apple", "unit": "g"}, {"ingredient_id": "ginger", "unit": "g"}, {"ingredient_id": "walnut", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b02','{"recipe_id": "b02", "method": [{"id": "main", "instructions": [{"en": "Simmer the oats with the soya drink for 5–8 minutes, stirring.", "es": "Cuece la avena con la bebida de soja durante 5–8 minutos, removiendo."}, {"en": "Slice the weighed peeled banana. Serve over the oats with the measured peanut butter.", "es": "Corta el plátano ya pelado y pesado. Sírvelo sobre la avena con la crema de cacahuete medida."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "oats", "unit": "g"}, {"ingredient_id": "soy_milk", "unit": "g"}, {"ingredient_id": "banana", "unit": "g"}, {"ingredient_id": "peanut_butter", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b03','{"recipe_id": "b03", "method": [{"id": "main", "instructions": [{"en": "Mix oats, yogurt and milk in a covered container. Refrigerate overnight, below 5°C.", "es": "Mezcla la avena, el yogur y la leche en un recipiente tapado. Refrigera toda la noche, a menos de 5 °C."}, {"en": "Wash the berries and add with the weighed pumpkin seeds before serving.", "es": "Lava los frutos rojos y añádelos con las pipas de calabaza pesadas justo antes de servir."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "oats", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}, {"ingredient_id": "milk", "unit": "g"}, {"ingredient_id": "blueberry", "unit": "g"}, {"ingredient_id": "raspberry", "unit": "g"}, {"ingredient_id": "pumpkin_seed", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b04','{"recipe_id": "b04", "method": [{"id": "main", "instructions": [{"en": "Wash and core the pear, keeping its skin; weigh the edible portion and dice.", "es": "Lava la pera y retira el corazón, conservando la piel; pesa la parte comestible y córtala."}, {"en": "Combine with yogurt, oats and chopped walnuts. Serve chilled.", "es": "Combina con el yogur, la avena y las nueces troceadas. Sirve frío."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "yogurt", "unit": "g"}, {"ingredient_id": "pear", "unit": "g"}, {"ingredient_id": "walnut", "unit": "g"}, {"ingredient_id": "oats", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b05','{"recipe_id": "b05", "method": [{"id": "main", "instructions": [{"en": "Toast the bread. Mash the weighed avocado flesh with lemon juice and salt.", "es": "Tuesta el pan. Machaca la pulpa de aguacate pesada con el zumo de limón y la sal."}, {"en": "Beat the weighed shell-free egg and cook in a non-stick pan with a splash of water until fully set.", "es": "Bate el huevo pesado sin cáscara y cocínalo en una sartén antiadherente con un poco de agua hasta que cuaje por completo."}, {"en": "Top the toast with avocado and cooked egg; no additional oil is included.", "es": "Reparte el aguacate y el huevo cocinado sobre la tostada; no se incluye aceite adicional."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "bread", "unit": "g"}, {"ingredient_id": "avocado", "unit": "g"}, {"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b06','{"recipe_id": "b06", "method": [{"id": "main", "instructions": [{"en": "Toast the bread and grate the washed tomato over it.", "es": "Tuesta el pan y ralla encima el tomate lavado."}, {"en": "Add the measured olive oil and pumpkin seeds. Serve with the peeled, weighed orange.", "es": "Añade el aceite de oliva y las pipas de calabaza medidos. Acompaña con la naranja pelada y pesada."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "bread", "unit": "g"}, {"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "pumpkin_seed", "unit": "g"}, {"ingredient_id": "orange", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b07','{"recipe_id": "b07", "method": [{"id": "main", "instructions": [{"en": "Wash spinach and tomato. Warm the measured oil and wilt the spinach.", "es": "Lava las espinacas y el tomate. Calienta el aceite medido y rehoga las espinacas."}, {"en": "Add the beaten shell-free egg and stir until fully set. Serve with toast and sliced tomato.", "es": "Añade el huevo batido sin cáscara y remueve hasta que cuaje por completo. Sirve con la tostada y el tomate cortado."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "spinach", "unit": "g"}, {"ingredient_id": "bread", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b08','{"recipe_id": "b08", "method": [{"id": "main", "instructions": [{"en": "Slice the mushrooms and cook them in the measured oil until their released liquid evaporates.", "es": "Corta los champiñones y cocínalos con el aceite medido hasta que se evapore el agua que suelten."}, {"en": "Add the beaten weighed egg, parsley and salt. Fold only after the egg is fully set; serve with bread.", "es": "Añade el huevo batido y pesado, el perejil y la sal. Dobla la tortilla cuando el huevo esté completamente cuajado; sirve con el pan."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "mushroom", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "bread", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b09','{"recipe_id": "b09", "method": [{"id": "main", "instructions": [{"en": "Blend the oats finely, then mix with the mashed banana, weighed shell-free egg, milk and baking powder.", "es": "Tritura la avena y mézclala con el plátano machacado, el huevo pesado sin cáscara, la leche y la levadura química."}, {"en": "Use the measured oil to grease a non-stick pan. Cook small pancakes on both sides until the centres are fully cooked, not wet.", "es": "Engrasa una sartén antiadherente con el aceite medido. Cocina tortitas pequeñas por ambos lados hasta que el centro esté completamente hecho, sin masa húmeda."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "oats", "unit": "g"}, {"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "banana", "unit": "g"}, {"ingredient_id": "milk", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "baking_powder", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b10','{"recipe_id": "b10", "method": [{"id": "main", "instructions": [{"en": "Peel and stone the mango, then weigh and dice the flesh.", "es": "Pela el mango, retira el hueso y pesa y corta la pulpa."}, {"en": "Combine with yogurt, oats and the measured sunflower seeds.", "es": "Mezcla con el yogur, la avena y las pipas de girasol medidas."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "yogurt", "unit": "g"}, {"ingredient_id": "mango", "unit": "g"}, {"ingredient_id": "sunflower_seed", "unit": "g"}, {"ingredient_id": "oats", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b11','{"recipe_id": "b11", "method": [{"id": "main", "instructions": [{"en": "Whisk cocoa into the soya drink. Add oats and simmer for 5–8 minutes, stirring.", "es": "Disuelve el cacao en la bebida de soja. Añade la avena y cuece suavemente durante 5–8 minutos, removiendo."}, {"en": "Top with the weighed banana slices and chopped almonds.", "es": "Añade por encima el plátano pesado y cortado y las almendras troceadas."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "oats", "unit": "g"}, {"ingredient_id": "soy_milk", "unit": "g"}, {"ingredient_id": "banana", "unit": "g"}, {"ingredient_id": "cocoa", "unit": "g"}, {"ingredient_id": "almond", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('b12','{"recipe_id": "b12", "method": [{"id": "main", "instructions": [{"en": "Prepare the chickpeas from their weighed dry amount using the separate soaking and boiling instructions.", "es": "Prepara los garbanzos a partir de su peso en seco siguiendo las instrucciones separadas de remojo y cocción."}, {"en": "Mash the cooked chickpeas with lemon, salt and measured oil. Spread onto toast and add tomato and parsley.", "es": "Machaca los garbanzos cocidos con el limón, la sal y el aceite medido. Extiende sobre la tostada y añade tomate y perejil."}]}], "whole": false, "bases": [{"component_id": "main", "ingredient_id": "chickpeas", "method": "plain_boiled", "soak": true}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "chickpeas", "unit": "g"}, {"ingredient_id": "bread", "unit": "g"}, {"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m01','{"recipe_id": "m01", "method": [{"id": "main", "instructions": [{"en": "Prepare the dry chickpeas separately. Soften the chopped onion and garlic in the measured oil.", "es": "Prepara aparte los garbanzos secos. Rehoga la cebolla y el ajo picados con el aceite medido."}, {"en": "Add tomatoes and simmer 10 minutes. Add the cooked chickpeas, then spinach; cook until the spinach is tender.", "es": "Añade el tomate y cuece 10 minutos. Incorpora los garbanzos cocidos y después las espinacas; cocina hasta que estén tiernas."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Wash and core the apple, weigh and chop; serve with the measured yogurt.", "es": "Lava la manzana y retira el corazón; pesa y corta la parte comestible y sirve con el yogur medido."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "chickpeas", "method": "plain_boiled", "soak": true}, {"component_id": "side", "ingredient_id": "rice_brown", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "chickpeas", "unit": "g"}, {"ingredient_id": "spinach", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "rice_brown", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "apple", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m02','{"recipe_id": "m02", "method": [{"id": "main", "instructions": [{"en": "Rinse the dry lentils. Soften onion, garlic and ginger in the measured oil.", "es": "Enjuaga las lentejas secas. Rehoga la cebolla, el ajo y el jengibre con el aceite medido."}, {"en": "Add lentils, tomatoes and enough water to cover generously. Simmer 20–25 minutes until the lentils are tender; stir in coconut milk and coriander.", "es": "Añade las lentejas, el tomate y suficiente agua para cubrir holgadamente. Cuece 20–25 minutos hasta que estén tiernas; incorpora la leche de coco y el cilantro."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Peel the orange, weigh its flesh and serve with the measured almonds.", "es": "Pela la naranja, pesa la pulpa y sirve con las almendras medidas."}]}], "whole": true, "bases": [{"component_id": "side", "ingredient_id": "rice_white", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "lentils_red", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "ginger", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "coconut_milk", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "coriander", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "rice_white", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "orange", "unit": "g"}, {"ingredient_id": "almond", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m03','{"recipe_id": "m03", "method": [{"id": "main", "instructions": [{"en": "Prepare the dry beans separately. Dice the vegetables and soften them in the measured oil.", "es": "Prepara aparte las alubias secas. Corta las verduras y rehógalas con el aceite medido."}, {"en": "Add tomatoes and a splash of water; simmer until the carrot is tender. Fold in cooked beans and basil and heat through.", "es": "Añade el tomate y un poco de agua; cuece hasta que la zanahoria esté tierna. Incorpora las alubias cocidas y la albahaca y calienta bien."}]}, {"id": "side", "instructions": [{"en": "Serve the weighed bread plain or lightly toasted; add no unlisted butter or oil.", "es": "Sirve el pan pesado, solo o ligeramente tostado; no añadas mantequilla ni aceite que no figuren en la receta."}]}, {"id": "dessert", "instructions": [{"en": "Wash and core the pear, weigh and dice; warm with the ginger and a little water until tender.", "es": "Lava la pera, retira el corazón, pesa y corta; calienta con el jengibre y un poco de agua hasta que esté tierna."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "beans_white", "method": "plain_boiled", "soak": true}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "beans_white", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "carrot", "unit": "g"}, {"ingredient_id": "celery", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "basil", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "bread", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "pear", "unit": "g"}, {"ingredient_id": "ginger", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m04','{"recipe_id": "m04", "method": [{"id": "main", "instructions": [{"en": "Soak and vigorously boil the dry kidney beans using their full preparation instructions before using them here.", "es": "Remoja y hierve enérgicamente las alubias rojas secas siguiendo todas sus instrucciones de preparación antes de usarlas aquí."}, {"en": "Soften onion, pepper and chilli in the measured oil. Add tomatoes and simmer 15 minutes, then add cooked beans and coriander and heat through.", "es": "Rehoga la cebolla, el pimiento y la guindilla con el aceite medido. Añade el tomate y cuece 15 minutos; incorpora las alubias cocidas y el cilantro y calienta bien."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Wash and weigh the berries, slice if needed and serve with the yogurt.", "es": "Lava y pesa los frutos rojos, córtalos si hace falta y sirve con el yogur."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "beans_kidney", "method": "plain_boiled", "soak": true}, {"component_id": "side", "ingredient_id": "quinoa", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "beans_kidney", "unit": "g"}, {"ingredient_id": "pepper_red", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "chilli", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "coriander", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "quinoa", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "strawberry", "unit": "g"}, {"ingredient_id": "blueberry", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m05','{"recipe_id": "m05", "method": [{"id": "main", "instructions": [{"en": "Cut the carrot and courgette into thin strips. Stir-fry with ginger and measured oil until tender.", "es": "Corta la zanahoria y el calabacín en tiras finas. Saltéalos con el jengibre y el aceite medido hasta que estén tiernos."}, {"en": "Fold in the source-matching plain steamed tofu gently with the soy sauce and cooked pasta. Heat through and sprinkle with sesame.", "es": "Incorpora con cuidado el tofu natural al vapor que corresponda a la referencia, la salsa de soja y la pasta cocida. Calienta bien y añade el sésamo."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Peel and weigh the banana. Stir cocoa into yogurt and add banana slices.", "es": "Pela y pesa el plátano. Mezcla el cacao con el yogur y añade el plátano cortado."}]}], "whole": false, "bases": [{"component_id": "side", "ingredient_id": "pasta_wholewheat", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "tofu", "unit": "g"}, {"ingredient_id": "carrot", "unit": "g"}, {"ingredient_id": "courgette", "unit": "g"}, {"ingredient_id": "ginger", "unit": "g"}, {"ingredient_id": "soy_sauce", "unit": "g"}, {"ingredient_id": "sesame", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "pasta_wholewheat", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "banana", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}, {"ingredient_id": "cocoa", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m06','{"recipe_id": "m06", "method": [{"id": "main", "instructions": [{"en": "Cook the weighed dry barley separately. Slice the leek and mushrooms.", "es": "Cuece aparte la cebada pesada en seco. Corta el puerro y los champiñones."}, {"en": "Cook leek and mushrooms in the measured oil with garlic until tender. Fold in barley, parsley and pumpkin seeds.", "es": "Cocina el puerro y los champiñones con el aceite medido y el ajo hasta que estén tiernos. Incorpora la cebada, el perejil y las pipas de calabaza."}]}, {"id": "dessert", "instructions": [{"en": "Remove peel and seeds, weigh the melon flesh and serve with washed mint.", "es": "Retira la piel y las semillas, pesa la pulpa del melón y sirve con menta lavada."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "barley", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "mushroom", "unit": "g"}, {"ingredient_id": "leek", "unit": "g"}, {"ingredient_id": "barley", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "pumpkin_seed", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "melon", "unit": "g"}, {"ingredient_id": "mint", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m07','{"recipe_id": "m07", "method": [{"id": "main", "instructions": [{"en": "Dice the peeled squash and courgette. Toss with measured oil and salt; roast at 200°C until tender, about 25–35 minutes.", "es": "Corta la calabaza pelada y el calabacín. Mezcla con el aceite medido y la sal; asa a 200 °C hasta que estén tiernos, unos 25–35 minutos."}, {"en": "Prepare the weighed dry couscous. Fold through the roasted vegetables, lemon, almonds and mint.", "es": "Prepara el cuscús pesado en seco. Mezcla con las verduras asadas, el limón, las almendras y la menta."}]}, {"id": "dessert", "instructions": [{"en": "Wash and weigh the edible grapes and serve with the measured walnut kernels.", "es": "Lava y pesa la parte comestible de las uvas y sirve con las nueces medidas."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "couscous", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "squash", "unit": "g"}, {"ingredient_id": "courgette", "unit": "g"}, {"ingredient_id": "couscous", "unit": "g"}, {"ingredient_id": "almond", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "mint", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "grapes", "unit": "g"}, {"ingredient_id": "walnut", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m08','{"recipe_id": "m08", "method": [{"id": "main", "instructions": [{"en": "Cook the weighed dry lentils separately. Soften finely diced carrot, onion and garlic in measured oil.", "es": "Cuece aparte las lentejas pesadas en seco. Rehoga la zanahoria, la cebolla y el ajo picados con el aceite medido."}, {"en": "Add tomatoes and simmer until the carrot is soft. Stir in cooked lentils and basil; serve over cooked spaghetti.", "es": "Añade el tomate y cuece hasta que la zanahoria esté blanda. Incorpora las lentejas cocidas y la albahaca; sirve sobre los espaguetis cocidos."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Peel both fruits, weigh the edible flesh, chop and combine.", "es": "Pela ambas frutas, pesa la parte comestible, corta y mezcla."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "lentils_green", "method": "plain_boiled", "soak": false}, {"component_id": "side", "ingredient_id": "pasta_wholewheat", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "lentils_green", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "carrot", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "basil", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "pasta_wholewheat", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "kiwi", "unit": "g"}, {"ingredient_id": "orange", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m09','{"recipe_id": "m09", "method": [{"id": "main", "instructions": [{"en": "Prepare the dry chickpeas separately. Dice aubergine and cook in measured oil, adding splashes of water rather than extra oil.", "es": "Prepara aparte los garbanzos secos. Corta la berenjena y cocínala con el aceite medido, añadiendo pequeñas cantidades de agua en vez de más aceite."}, {"en": "Add ginger, garlic, chilli, tomatoes and coconut milk. Simmer until the aubergine is tender; add cooked chickpeas and heat through.", "es": "Añade el jengibre, el ajo, la guindilla, el tomate y la leche de coco. Cuece hasta que la berenjena esté tierna; incorpora los garbanzos cocidos y calienta bien."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Wash and core the apple, weigh and chop; serve with the measured yogurt.", "es": "Lava la manzana y retira el corazón; pesa y corta la parte comestible y sirve con el yogur medido."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "chickpeas", "method": "plain_boiled", "soak": true}, {"component_id": "side", "ingredient_id": "rice_white", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "chickpeas", "unit": "g"}, {"ingredient_id": "aubergine", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "coconut_milk", "unit": "g"}, {"ingredient_id": "ginger", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "chilli", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "rice_white", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "apple", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m10','{"recipe_id": "m10", "method": [{"id": "main", "instructions": [{"en": "Soften onion, pepper and garlic in measured oil. Add tomatoes and simmer 15 minutes.", "es": "Rehoga la cebolla, el pimiento y el ajo con el aceite medido. Añade el tomate y cuece 15 minutos."}, {"en": "Make shallow wells, add the weighed shell-free egg and cover. Cook until both white and yolk are fully set; finish with parsley.", "es": "Forma huecos, añade el huevo pesado sin cáscara y tapa. Cocina hasta que la clara y la yema estén completamente cuajadas; termina con perejil."}]}, {"id": "side", "instructions": [{"en": "Serve the weighed bread plain or lightly toasted; add no unlisted butter or oil.", "es": "Sirve el pan pesado, solo o ligeramente tostado; no añadas mantequilla ni aceite que no figuren en la receta."}]}, {"id": "dessert", "instructions": [{"en": "Peel the orange, weigh its flesh and serve with the measured almonds.", "es": "Pela la naranja, pesa la pulpa y sirve con las almendras medidas."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "pepper_red", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "bread", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "orange", "unit": "g"}, {"ingredient_id": "almond", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m11','{"recipe_id": "m11", "method": [{"id": "main", "instructions": [{"en": "Slice the raw peeled potato thinly. Steam or microwave with a little water until tender; drain.", "es": "Corta la patata cruda pelada en láminas finas. Cuécela al vapor o en microondas con un poco de agua hasta que esté tierna; escurre."}, {"en": "Soften onion in the measured oil, then add potato and beaten egg. Cook gently on both sides until fully set throughout.", "es": "Rehoga la cebolla con el aceite medido; añade la patata y el huevo batido. Cocina suavemente por ambos lados hasta que esté completamente cuajada."}]}, {"id": "side", "instructions": [{"en": "Wash and chop the vegetables. Toss with the measured oil and vinegar.", "es": "Lava y corta las verduras. Mézclalas con el aceite y el vinagre medidos."}]}, {"id": "dessert", "instructions": [{"en": "Wash and core the pear, weigh and dice; warm with the ginger and a little water until tender.", "es": "Lava la pera, retira el corazón, pesa y corta; calienta con el jengibre y un poco de agua hasta que esté tierna."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "potato", "unit": "g"}, {"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "cucumber", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "vinegar", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "pear", "unit": "g"}, {"ingredient_id": "ginger", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m12','{"recipe_id": "m12", "method": [{"id": "main", "instructions": [{"en": "Rinse and cook the weighed dry quinoa. Wilt spinach and garlic in the measured oil.", "es": "Lava y cuece la quinoa pesada en seco. Rehoga las espinacas y el ajo con el aceite medido."}, {"en": "Combine quinoa, spinach, chopped tomato, almonds and lemon juice; serve warm.", "es": "Combina la quinoa, las espinacas, el tomate cortado, las almendras y el zumo de limón; sirve templado."}]}, {"id": "dessert", "instructions": [{"en": "Wash and weigh the berries, slice if needed and serve with the yogurt.", "es": "Lava y pesa los frutos rojos, córtalos si hace falta y sirve con el yogur."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "quinoa", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "quinoa", "unit": "g"}, {"ingredient_id": "spinach", "unit": "g"}, {"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "almond", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "strawberry", "unit": "g"}, {"ingredient_id": "blueberry", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m13','{"recipe_id": "m13", "method": [{"id": "main", "instructions": [{"en": "Prepare the dry beans separately. Roast pepper strips with measured oil at 200°C until tender.", "es": "Prepara aparte las alubias secas. Asa el pimiento en tiras con el aceite medido a 200 °C hasta que esté tierno."}, {"en": "Mash the cooked beans with lemon, garlic and salt. Fill the warmed pitta with the bean mixture, peppers and washed rocket.", "es": "Machaca las alubias cocidas con el limón, el ajo y la sal. Rellena la pita caliente con la mezcla, el pimiento y la rúcula lavada."}]}, {"id": "dessert", "instructions": [{"en": "Peel and weigh the banana. Stir cocoa into yogurt and add banana slices.", "es": "Pela y pesa el plátano. Mezcla el cacao con el yogur y añade el plátano cortado."}]}], "whole": false, "bases": [{"component_id": "main", "ingredient_id": "beans_white", "method": "plain_boiled", "soak": true}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "beans_white", "unit": "g"}, {"ingredient_id": "pitta", "unit": "g"}, {"ingredient_id": "pepper_red", "unit": "g"}, {"ingredient_id": "rocket", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "banana", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}, {"ingredient_id": "cocoa", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m14','{"recipe_id": "m14", "method": [{"id": "main", "instructions": [{"en": "Cook the weighed dry barley. Boil frozen peas until cooked through, following the packet.", "es": "Cuece la cebada pesada en seco. Hierve los guisantes congelados hasta que estén hechos, siguiendo el envase."}, {"en": "Soften sliced spring onion in measured oil, then combine with barley, peas, lemon, mint and pumpkin seeds.", "es": "Rehoga la cebolleta cortada con el aceite medido; mezcla con la cebada, los guisantes, el limón, la menta y las pipas de calabaza."}]}, {"id": "dessert", "instructions": [{"en": "Remove peel and seeds, weigh the melon flesh and serve with washed mint.", "es": "Retira la piel y las semillas, pesa la pulpa del melón y sirve con menta lavada."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "barley", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "peas", "unit": "g"}, {"ingredient_id": "barley", "unit": "g"}, {"ingredient_id": "spring_onion", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "mint", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "pumpkin_seed", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "melon", "unit": "g"}, {"ingredient_id": "mint", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m15','{"recipe_id": "m15", "method": [{"id": "main", "instructions": [{"en": "Soften onion and pepper in measured oil. Add garlic and beef mince and break it up as it cooks.", "es": "Rehoga la cebolla y el pimiento con el aceite medido. Añade el ajo y la carne picada, separándola mientras se cocina."}, {"en": "Add tomatoes and simmer until the mince is thoroughly cooked; check the core-temperature instruction. Serve with bulgur and parsley.", "es": "Añade el tomate y cuece hasta que la carne esté completamente hecha; comprueba la indicación de temperatura interior. Sirve con bulgur y perejil."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Wash and weigh the edible grapes and serve with the measured walnut kernels.", "es": "Lava y pesa la parte comestible de las uvas y sirve con las nueces medidas."}]}], "whole": true, "bases": [{"component_id": "side", "ingredient_id": "bulgur", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "beef", "unit": "g"}, {"ingredient_id": "pepper_red", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "bulgur", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "grapes", "unit": "g"}, {"ingredient_id": "walnut", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m16','{"recipe_id": "m16", "method": [{"id": "main", "instructions": [{"en": "Finely mince the weighed turkey light meat; mix with oats, weighed egg and half the garlic, then shape small meatballs.", "es": "Pica finamente la carne blanca de pavo pesada; mezcla con la avena, el huevo pesado y la mitad del ajo y forma albóndigas pequeñas."}, {"en": "Soften onion and remaining garlic in measured oil. Add tomatoes and meatballs, cover and simmer until cooked through; check their centres reach the specified safe temperature.", "es": "Rehoga la cebolla y el ajo restante con el aceite medido. Añade el tomate y las albóndigas, tapa y cuece hasta que estén hechas; comprueba que el centro alcance la temperatura segura indicada."}, {"en": "Serve with cooked pasta and basil.", "es": "Sirve con la pasta cocida y la albahaca."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Peel both fruits, weigh the edible flesh, chop and combine.", "es": "Pela ambas frutas, pesa la parte comestible, corta y mezcla."}]}], "whole": true, "bases": [{"component_id": "side", "ingredient_id": "pasta", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "turkey", "unit": "g"}, {"ingredient_id": "oats", "unit": "g"}, {"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "basil", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "pasta", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "kiwi", "unit": "g"}, {"ingredient_id": "orange", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m17','{"recipe_id": "m17", "method": [{"id": "main", "instructions": [{"en": "Cut peeled potato into small cubes. Toss with half the measured oil and roast at 200°C for 15 minutes.", "es": "Corta la patata pelada en dados pequeños. Mezcla con la mitad del aceite medido y asa a 200 °C durante 15 minutos."}, {"en": "Add chicken coated with remaining oil, lemon and garlic. Roast until the potato is tender and the chicken reaches the safe core temperature; steam broccoli separately.", "es": "Añade el pollo con el aceite restante, el limón y el ajo. Asa hasta que la patata esté tierna y el pollo alcance la temperatura interior segura; cuece el brócoli al vapor aparte."}, {"en": "Serve together with parsley and the listed salt.", "es": "Sirve todo junto con el perejil y la sal indicada."}]}, {"id": "dessert", "instructions": [{"en": "Wash and core the apple, weigh and chop; serve with the measured yogurt.", "es": "Lava la manzana y retira el corazón; pesa y corta la parte comestible y sirve con el yogur medido."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "chicken", "unit": "g"}, {"ingredient_id": "potato", "unit": "g"}, {"ingredient_id": "broccoli", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "apple", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m18','{"recipe_id": "m18", "method": [{"id": "main", "instructions": [{"en": "Cook the weighed dry rice separately. Slice chicken and vegetables into strips.", "es": "Cuece aparte el arroz pesado en seco. Corta el pollo y las verduras en tiras."}, {"en": "Cook chicken in measured oil until it reaches the safe core temperature. Add onion and peppers and cook until tender; fold in rice, lime and coriander.", "es": "Cocina el pollo con el aceite medido hasta que alcance la temperatura interior segura. Añade la cebolla y los pimientos y cocina hasta que estén tiernos; incorpora el arroz, la lima y el cilantro."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Peel the orange, weigh its flesh and serve with the measured almonds.", "es": "Pela la naranja, pesa la pulpa y sirve con las almendras medidas."}]}], "whole": true, "bases": [{"component_id": "side", "ingredient_id": "rice_white", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "chicken", "unit": "g"}, {"ingredient_id": "pepper_red", "unit": "g"}, {"ingredient_id": "pepper_green", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lime_juice", "unit": "g"}, {"ingredient_id": "coriander", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "rice_white", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "orange", "unit": "g"}, {"ingredient_id": "almond", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m19','{"recipe_id": "m19", "method": [{"id": "main", "instructions": [{"en": "Cook the dry rice and boil the trimmed green beans until tender. Slice pork into medallions and the cored apple into wedges.", "es": "Cuece el arroz en seco y hierve las judías verdes limpias hasta que estén tiernas. Corta el cerdo en medallones y la manzana sin corazón en gajos."}, {"en": "Cook pork in measured oil until it reaches the safe core temperature. Add onion and apple with a splash of water, cover until tender and stir in mustard.", "es": "Cocina el cerdo con el aceite medido hasta que alcance la temperatura interior segura. Añade cebolla y manzana con un poco de agua, tapa hasta que estén tiernas e incorpora la mostaza."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Wash and core the pear, weigh and dice; warm with the ginger and a little water until tender.", "es": "Lava la pera, retira el corazón, pesa y corta; calienta con el jengibre y un poco de agua hasta que esté tierna."}]}], "whole": true, "bases": [{"component_id": "side", "ingredient_id": "rice_brown", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "pork", "unit": "g"}, {"ingredient_id": "apple", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "mustard", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "green_beans", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "rice_brown", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "pear", "unit": "g"}, {"ingredient_id": "ginger", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m20','{"recipe_id": "m20", "method": [{"id": "main", "instructions": [{"en": "Boil or steam the weighed raw potato and trimmed green beans until tender.", "es": "Hierve o cuece al vapor la patata pesada en crudo y las judías verdes limpias hasta que estén tiernas."}, {"en": "Bake salmon with measured oil, lemon and dill at 190°C until fully cooked and safely hot in the centre. Serve with the vegetables.", "es": "Hornea el salmón con el aceite medido, el limón y el eneldo a 190 °C hasta que esté completamente cocinado y a temperatura segura en el centro. Sirve con las verduras."}]}, {"id": "dessert", "instructions": [{"en": "Wash and weigh the berries, slice if needed and serve with the yogurt.", "es": "Lava y pesa los frutos rojos, córtalos si hace falta y sirve con el yogur."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "salmon", "unit": "g"}, {"ingredient_id": "potato", "unit": "g"}, {"ingredient_id": "green_beans", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "dill", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "strawberry", "unit": "g"}, {"ingredient_id": "blueberry", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m21','{"recipe_id": "m21", "method": [{"id": "main", "instructions": [{"en": "Prepare the dry chickpeas separately. Soften onion and garlic in measured oil, add tomatoes and simmer 10 minutes.", "es": "Prepara aparte los garbanzos secos. Rehoga cebolla y ajo con el aceite medido, añade el tomate y cuece 10 minutos."}, {"en": "Add cooked chickpeas and nestle cod into the sauce. Cover until the fish is safely cooked through, then wilt in spinach and add parsley.", "es": "Añade los garbanzos cocidos y coloca el bacalao en la salsa. Tapa hasta que el pescado esté completamente cocinado a temperatura segura; incorpora las espinacas y el perejil."}]}, {"id": "dessert", "instructions": [{"en": "Peel and weigh the banana. Stir cocoa into yogurt and add banana slices.", "es": "Pela y pesa el plátano. Mezcla el cacao con el yogur y añade el plátano cortado."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "chickpeas", "method": "plain_boiled", "soak": true}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "cod", "unit": "g"}, {"ingredient_id": "chickpeas", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "spinach", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "banana", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}, {"ingredient_id": "cocoa", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m22','{"recipe_id": "m22", "method": [{"id": "main", "instructions": [{"en": "Cook the weighed dry rice. Boil the frozen peas following the packet and drain.", "es": "Cuece el arroz pesado en seco. Hierve los guisantes congelados siguiendo el envase y escurre."}, {"en": "Heat measured oil and garlic; add raw edible prawns and cook thoroughly to the safe core-temperature instruction. Fold through rice, peas, lemon and parsley.", "es": "Calienta el aceite medido y el ajo; añade los langostinos crudos sin partes no comestibles y cocina hasta alcanzar la temperatura interior segura indicada. Incorpora el arroz, los guisantes, el limón y el perejil."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Remove peel and seeds, weigh the melon flesh and serve with washed mint.", "es": "Retira la piel y las semillas, pesa la pulpa del melón y sirve con menta lavada."}]}], "whole": true, "bases": [{"component_id": "side", "ingredient_id": "rice_white", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "prawns", "unit": "g"}, {"ingredient_id": "peas", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "rice_white", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "melon", "unit": "g"}, {"ingredient_id": "mint", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m23','{"recipe_id": "m23", "method": [{"id": "main", "instructions": [{"en": "Drain and weigh tuna. Cook the weighed dry pasta, then drain.", "es": "Escurre y pesa el atún. Cuece la pasta pesada en seco y escurre."}, {"en": "Toss pasta with tuna, chopped washed tomato, rocket, measured oil, lemon and basil; serve immediately.", "es": "Mezcla la pasta con el atún, el tomate lavado y cortado, la rúcula, el aceite medido, el limón y la albahaca; sirve enseguida."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Wash and weigh the edible grapes and serve with the measured walnut kernels.", "es": "Lava y pesa la parte comestible de las uvas y sirve con las nueces medidas."}]}], "whole": false, "bases": [{"component_id": "side", "ingredient_id": "pasta", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "tuna", "unit": "g"}, {"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "rocket", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "basil", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "pasta", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "grapes", "unit": "g"}, {"ingredient_id": "walnut", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m24','{"recipe_id": "m24", "method": [{"id": "main", "instructions": [{"en": "Drain the sardines before weighing. Toast the bread and top with washed sliced tomato.", "es": "Escurre las sardinas antes de pesarlas. Tuesta el pan y coloca encima el tomate lavado y cortado."}, {"en": "Add sardines, lemon and parsley. The source nutrition already includes retained oil; no additional oil is listed.", "es": "Añade las sardinas, el limón y el perejil. Los valores de referencia ya incluyen el aceite retenido; no se añade aceite adicional."}]}, {"id": "side", "instructions": [{"en": "Wash and chop the vegetables. Toss with the measured oil and vinegar.", "es": "Lava y corta las verduras. Mézclalas con el aceite y el vinagre medidos."}]}, {"id": "dessert", "instructions": [{"en": "Peel both fruits, weigh the edible flesh, chop and combine.", "es": "Pela ambas frutas, pesa la parte comestible, corta y mezcla."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "sardines", "unit": "g"}, {"ingredient_id": "bread", "unit": "g"}, {"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "cucumber", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "vinegar", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "kiwi", "unit": "g"}, {"ingredient_id": "orange", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m25','{"recipe_id": "m25", "method": [{"id": "main", "instructions": [{"en": "Soften onion and mushrooms in measured oil. Add extra-lean beef mince and cook thoroughly, breaking it apart.", "es": "Rehoga la cebolla y los champiñones con el aceite medido. Añade la ternera picada extramagra y cocina completamente, separándola."}, {"en": "Check the safe core temperature, then remove from the heat and stir in yogurt and mustard without boiling. Serve with rice and parsley.", "es": "Comprueba la temperatura interior segura; retira del fuego e incorpora el yogur y la mostaza sin hervir. Sirve con arroz y perejil."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Wash and core the apple, weigh and chop; serve with the measured yogurt.", "es": "Lava la manzana y retira el corazón; pesa y corta la parte comestible y sirve con el yogur medido."}]}], "whole": false, "bases": [{"component_id": "side", "ingredient_id": "rice_brown", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "beef", "unit": "g"}, {"ingredient_id": "mushroom", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}, {"ingredient_id": "mustard", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "rice_brown", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "apple", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m26','{"recipe_id": "m26", "method": [{"id": "main", "instructions": [{"en": "Cook the weighed quinoa. Slice turkey and carrot; cook them in measured oil with splashes of water as needed.", "es": "Cuece la quinoa pesada. Corta el pavo y la zanahoria y cocínalos con el aceite medido y pequeñas cantidades de agua si hacen falta."}, {"en": "Check that the turkey reaches the safe core temperature. Add spinach to wilt, then combine with quinoa, lemon and parsley.", "es": "Comprueba que el pavo alcance la temperatura interior segura. Añade las espinacas para rehogarlas y mezcla con la quinoa, el limón y el perejil."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Peel the orange, weigh its flesh and serve with the measured almonds.", "es": "Pela la naranja, pesa la pulpa y sirve con las almendras medidas."}]}], "whole": true, "bases": [{"component_id": "side", "ingredient_id": "quinoa", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "turkey", "unit": "g"}, {"ingredient_id": "spinach", "unit": "g"}, {"ingredient_id": "carrot", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "quinoa", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "orange", "unit": "g"}, {"ingredient_id": "almond", "unit": "g"}]}]}'::jsonb);
