insert into app_private.cooking_rules values('m28','{"recipe_id": "m28", "method": [{"id": "main", "instructions": [{"en": "Prepare the dry bulgur. Cook thin pork strips in measured oil until they reach the safe core temperature.", "es": "Prepara el bulgur seco. Cocina el cerdo en tiras finas con el aceite medido hasta que alcance la temperatura interior segura."}, {"en": "Add onion, pepper and garlic; soften, then add tomatoes and simmer until the vegetables are tender. Serve with bulgur and parsley.", "es": "Añade la cebolla, el pimiento y el ajo; rehoga e incorpora el tomate. Cuece hasta que las verduras estén tiernas y sirve con bulgur y perejil."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Wash and weigh the berries, slice if needed and serve with the yogurt.", "es": "Lava y pesa los frutos rojos, córtalos si hace falta y sirve con el yogur."}]}], "whole": true, "bases": [{"component_id": "side", "ingredient_id": "bulgur", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "pork", "unit": "g"}, {"ingredient_id": "pepper_red", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "bulgur", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "strawberry", "unit": "g"}, {"ingredient_id": "blueberry", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m29','{"recipe_id": "m29", "method": [{"id": "main", "instructions": [{"en": "Cook the weighed dry rice. Bake salmon with measured oil at 190°C until safely cooked through.", "es": "Cuece el arroz pesado en seco. Hornea el salmón con el aceite medido a 190 °C hasta que esté completamente cocinado a temperatura segura."}, {"en": "Combine warm rice with salmon, washed chopped tomato and cucumber, lemon and dill. Serve immediately.", "es": "Combina el arroz templado con el salmón, el tomate y el pepino lavados y cortados, el limón y el eneldo. Sirve enseguida."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Peel and weigh the banana. Stir cocoa into yogurt and add banana slices.", "es": "Pela y pesa el plátano. Mezcla el cacao con el yogur y añade el plátano cortado."}]}], "whole": false, "bases": [{"component_id": "side", "ingredient_id": "rice_brown", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "salmon", "unit": "g"}, {"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "cucumber", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "dill", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "rice_brown", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "banana", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}, {"ingredient_id": "cocoa", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m30','{"recipe_id": "m30", "method": [{"id": "main", "instructions": [{"en": "Cut potato into small cubes, toss with measured oil and roast at 200°C until nearly tender.", "es": "Corta la patata en dados pequeños, mezcla con el aceite medido y asa a 200 °C hasta que esté casi tierna."}, {"en": "Add cod with garlic and lemon, and frozen peas with a little water. Cover and continue until fish reaches a safe core temperature and peas are cooked; add parsley.", "es": "Añade el bacalao con ajo y limón y los guisantes congelados con un poco de agua. Tapa y continúa hasta que el pescado alcance una temperatura interior segura y los guisantes estén hechos; añade perejil."}]}, {"id": "dessert", "instructions": [{"en": "Remove peel and seeds, weigh the melon flesh and serve with washed mint.", "es": "Retira la piel y las semillas, pesa la pulpa del melón y sirve con menta lavada."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "cod", "unit": "g"}, {"ingredient_id": "potato", "unit": "g"}, {"ingredient_id": "peas", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "melon", "unit": "g"}, {"ingredient_id": "mint", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m31','{"recipe_id": "m31", "method": [{"id": "main", "instructions": [{"en": "Cook the weighed dry lentils. Cut cauliflower and carrot, toss with measured oil and roast at 200°C until tender and lightly coloured.", "es": "Cuece las lentejas pesadas en seco. Corta la coliflor y la zanahoria, mezcla con el aceite medido y asa a 200 °C hasta que estén tiernas y ligeramente doradas."}, {"en": "Toss with cooked lentils, lemon, parsley and pumpkin seeds; serve warm.", "es": "Mezcla con las lentejas cocidas, el limón, el perejil y las pipas de calabaza; sirve templado."}]}, {"id": "dessert", "instructions": [{"en": "Wash and weigh the edible grapes and serve with the measured walnut kernels.", "es": "Lava y pesa la parte comestible de las uvas y sirve con las nueces medidas."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "lentils_green", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "cauliflower", "unit": "g"}, {"ingredient_id": "lentils_green", "unit": "g"}, {"ingredient_id": "carrot", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "lemon_juice", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "pumpkin_seed", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "grapes", "unit": "g"}, {"ingredient_id": "walnut", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m32','{"recipe_id": "m32", "method": [{"id": "main", "instructions": [{"en": "Cook the quinoa and steam broccoli until tender. Warm measured oil and ginger in a pan.", "es": "Cuece la quinoa y cocina el brócoli al vapor hasta que esté tierno. Calienta el aceite medido y el jengibre en una sartén."}, {"en": "Add the source-matching plain steamed tofu gently, broccoli and soy sauce. Heat through, then serve with quinoa and sesame.", "es": "Añade con cuidado el tofu natural al vapor que corresponda a la referencia, el brócoli y la salsa de soja. Calienta bien y sirve con quinoa y sésamo."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Peel both fruits, weigh the edible flesh, chop and combine.", "es": "Pela ambas frutas, pesa la parte comestible, corta y mezcla."}]}], "whole": true, "bases": [{"component_id": "side", "ingredient_id": "quinoa", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "tofu", "unit": "g"}, {"ingredient_id": "broccoli", "unit": "g"}, {"ingredient_id": "ginger", "unit": "g"}, {"ingredient_id": "soy_sauce", "unit": "g"}, {"ingredient_id": "sesame", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "quinoa", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "kiwi", "unit": "g"}, {"ingredient_id": "orange", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m33','{"recipe_id": "m33", "method": [{"id": "main", "instructions": [{"en": "Prepare the dry beans separately. Dice the raw peeled sweet potato and simmer with onion, garlic, tomatoes and measured oil, adding water as needed.", "es": "Prepara aparte las alubias secas. Corta el boniato crudo pelado y cuécelo con la cebolla, el ajo, el tomate y el aceite medido, añadiendo agua si hace falta."}, {"en": "When the sweet potato is tender, add the cooked beans, heat through and finish with coriander.", "es": "Cuando el boniato esté tierno, añade las alubias cocidas, calienta bien y termina con cilantro."}]}, {"id": "dessert", "instructions": [{"en": "Wash and core the apple, weigh and chop; serve with the measured yogurt.", "es": "Lava la manzana y retira el corazón; pesa y corta la parte comestible y sirve con el yogur medido."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "beans_blackeye", "method": "plain_boiled", "soak": true}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "beans_blackeye", "unit": "g"}, {"ingredient_id": "sweet_potato", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "coriander", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "apple", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m34','{"recipe_id": "m34", "method": [{"id": "main", "instructions": [{"en": "Cook pasta and frozen peas separately. Warm measured oil with garlic and wilt the spinach.", "es": "Cuece la pasta y los guisantes congelados por separado. Calienta el aceite medido con el ajo y rehoga las espinacas."}, {"en": "Take the pan off the heat and mix in yogurt, cooked peas and pasta, loosening with a little cooking water. Add basil; do not boil the yogurt sauce.", "es": "Retira la sartén del fuego y mezcla el yogur, los guisantes cocidos y la pasta, aligerando con un poco de agua de cocción. Añade albahaca; no hiervas la salsa de yogur."}]}, {"id": "side", "instructions": [{"en": "Cook the weighed dry grain using its preparation instructions; serve with the main dish.", "es": "Cocina el cereal pesado en seco siguiendo sus instrucciones de preparación y sírvelo con el plato principal."}]}, {"id": "dessert", "instructions": [{"en": "Peel the orange, weigh its flesh and serve with the measured almonds.", "es": "Pela la naranja, pesa la pulpa y sirve con las almendras medidas."}]}], "whole": true, "bases": [{"component_id": "side", "ingredient_id": "pasta_wholewheat", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "peas", "unit": "g"}, {"ingredient_id": "spinach", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "basil", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "side", "ingredients": [{"ingredient_id": "pasta_wholewheat", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "orange", "unit": "g"}, {"ingredient_id": "almond", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m35','{"recipe_id": "m35", "method": [{"id": "main", "instructions": [{"en": "Prepare dry chickpeas and couscous separately. Halve and deseed the peppers; soften them at 200°C for 15 minutes.", "es": "Prepara por separado los garbanzos secos y el cuscús. Parte los pimientos y retira las semillas; ablanda en el horno a 200 °C durante 15 minutos."}, {"en": "Cook mushrooms in measured oil, then combine with cooked chickpeas, couscous, tomatoes and parsley. Fill peppers and bake until tender and hot throughout.", "es": "Cocina los champiñones con el aceite medido y mezcla con los garbanzos cocidos, el cuscús, el tomate y el perejil. Rellena los pimientos y hornea hasta que estén tiernos y bien calientes."}]}, {"id": "dessert", "instructions": [{"en": "Wash and core the pear, weigh and dice; warm with the ginger and a little water until tender.", "es": "Lava la pera, retira el corazón, pesa y corta; calienta con el jengibre y un poco de agua hasta que esté tierna."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "chickpeas", "method": "plain_boiled", "soak": true}, {"component_id": "main", "ingredient_id": "couscous", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "pepper_red", "unit": "g"}, {"ingredient_id": "chickpeas", "unit": "g"}, {"ingredient_id": "mushroom", "unit": "g"}, {"ingredient_id": "couscous", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "pear", "unit": "g"}, {"ingredient_id": "ginger", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('m36','{"recipe_id": "m36", "method": [{"id": "main", "instructions": [{"en": "Cook the weighed lentils. Boil the weighed raw potato and mash it with a little cooking water, without unlisted butter or milk.", "es": "Cuece las lentejas pesadas. Hierve la patata pesada en crudo y cháfala con un poco de agua de cocción, sin añadir mantequilla ni leche que no estén indicadas."}, {"en": "Soften onion, carrot and courgette in measured oil. Add tomatoes, cooked lentils and basil; simmer until tender.", "es": "Rehoga la cebolla, la zanahoria y el calabacín con el aceite medido. Añade tomate, lentejas cocidas y albahaca; cuece hasta que estén tiernos."}, {"en": "Put the filling in an oven dish, top with mash and bake at 200°C until bubbling and lightly coloured.", "es": "Coloca el relleno en una fuente, cubre con el puré y hornea a 200 °C hasta que burbujee y se dore ligeramente."}]}, {"id": "dessert", "instructions": [{"en": "Wash and weigh the berries, slice if needed and serve with the yogurt.", "es": "Lava y pesa los frutos rojos, córtalos si hace falta y sirve con el yogur."}]}], "whole": true, "bases": [{"component_id": "main", "ingredient_id": "lentils_green", "method": "plain_boiled", "soak": false}], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "lentils_green", "unit": "g"}, {"ingredient_id": "potato", "unit": "g"}, {"ingredient_id": "courgette", "unit": "g"}, {"ingredient_id": "carrot", "unit": "g"}, {"ingredient_id": "tomato_canned", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "basil", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}, {"id": "dessert", "ingredients": [{"ingredient_id": "strawberry", "unit": "g"}, {"ingredient_id": "blueberry", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_tomato_mozzarella_toast','{"recipe_id": "global_tomato_mozzarella_toast", "method": [{"id": "main", "instructions": [{"en": "Roast halved tomatoes with oil, vinegar and thyme at 200°C (180°C fan) for 30 minutes.", "es": "Asa los tomates partidos con aceite, vinagre y tomillo a 200°C (180°C con ventilador) durante 30 minutos."}, {"en": "Toast the bread; add the tomatoes, mozzarella, basil and rocket, then drizzle with the remaining oil.", "es": "Tuesta el pan y añade tomates, mozzarella, albahaca y rúcula. Termina con el aceite restante."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "balsamic_vinegar", "unit": "g"}, {"ingredient_id": "thyme", "unit": "g"}, {"ingredient_id": "bread", "unit": "g"}, {"ingredient_id": "mozzarella", "unit": "g"}, {"ingredient_id": "basil", "unit": "g"}, {"ingredient_id": "rocket", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_banana_bread','{"recipe_id": "global_banana_bread", "method": [{"id": "main", "instructions": [{"en": "Line a loaf tin. Cream butter and sugar, beat in eggs, then fold in flour, baking powder and mashed banana.", "es": "Forra un molde. Bate mantequilla y azúcar, incorpora los huevos y mezcla harina, levadura y plátano machacado."}, {"en": "Bake at 180°C (160°C fan), checking from 30–40 minutes; allow about 50 minutes, until a skewer comes out clean. Cool before icing.", "es": "Hornea a 180°C (160°C con ventilador). Comprueba desde los 30–40 minutos; calcula unos 50, hasta que la brocheta salga limpia. Enfría antes de glasear."}, {"en": "Mix icing sugar with water, drizzle over the loaf and finish with banana chips.", "es": "Mezcla azúcar glas y agua, reparte sobre el bizcocho y termina con chips de plátano."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "butter", "unit": "g"}, {"ingredient_id": "sugar", "unit": "g"}, {"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "self_raising_flour", "unit": "g"}, {"ingredient_id": "baking_powder", "unit": "g"}, {"ingredient_id": "banana", "unit": "g"}, {"ingredient_id": "icing_sugar", "unit": "g"}, {"ingredient_id": "water", "unit": "g"}, {"ingredient_id": "banana_chips", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_scrambled_toast','{"recipe_id": "global_scrambled_toast", "method": [{"id": "main", "instructions": [{"en": "Beat eggs with pepper. Warm the milk in a non-stick pan, add the eggs and stir gently until softly set.", "es": "Bate los huevos con pimienta. Calienta la leche en una sartén antiadherente, incorpora los huevos y remueve hasta que cuajen suavemente."}, {"en": "Toast the bread, spread it lightly and serve with the eggs.", "es": "Tuesta el pan, unta la margarina y sirve con los huevos."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "bread", "unit": "g"}, {"ingredient_id": "low_fat_spread", "unit": "g"}, {"ingredient_id": "milk", "unit": "g"}, {"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "black_pepper", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_spinach_omelette','{"recipe_id": "global_spinach_omelette", "method": [{"id": "main", "instructions": [{"en": "Soften chopped onion in half the oil. Wilt the spinach, then cool slightly and mix with beaten eggs, cheese and seasoning.", "es": "Ablanda la cebolla picada con la mitad del aceite. Añade las espinacas, deja templar y mezcla con huevos batidos, queso y condimentos."}, {"en": "Heat the remaining oil, add the mixture and cook 5–7 minutes. Turn carefully and cook the other side until set.", "es": "Calienta el aceite restante, vierte la mezcla y cocina 5–7 minutos. Da la vuelta con cuidado y termina de cuajar."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "spinach", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "feta", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}, {"ingredient_id": "black_pepper", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_potato_noodle_soup','{"recipe_id": "global_potato_noodle_soup", "method": [{"id": "main", "instructions": [{"en": "Soften sliced onion and diced potatoes in the oil. Add water and simmer until tender.", "es": "Rehoga la cebolla en tiras y la patata en dados con el aceite. Añade el agua y cuece hasta que estén tiernas."}, {"en": "Add sugar and tomato concentrate, reduce to the desired consistency, then cook the vermicelli in the soup and season.", "es": "Añade azúcar y concentrado de tomate. Reduce a tu gusto, cuece los fideos en la sopa y salpimenta."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "vegetable_oil", "unit": "g"}, {"ingredient_id": "pasta", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "potato", "unit": "g"}, {"ingredient_id": "sugar", "unit": "g"}, {"ingredient_id": "tomato_puree", "unit": "g"}, {"ingredient_id": "water", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}, {"ingredient_id": "black_pepper", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_burger','{"recipe_id": "global_burger", "method": [{"id": "main", "instructions": [{"en": "Mix mince, chopped onion and egg. Shape four evenly thick patties, chill for 30 minutes and brush with oil.", "es": "Mezcla carne picada, cebolla y huevo. Forma cuatro hamburguesas de grosor uniforme, enfría 30 minutos y pincela con aceite."}, {"en": "Cook on a hot barbecue, turning once, until thoroughly cooked. Serve in the split rolls.", "es": "Cocina a la barbacoa, dando la vuelta, hasta que estén bien hechas. Sirve en los panes abiertos."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "beef", "unit": "g"}, {"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "vegetable_oil", "unit": "g"}, {"ingredient_id": "burger_roll", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_quesadilla','{"recipe_id": "global_quesadilla", "method": [{"id": "main", "instructions": [{"en": "Spread salsa over the tortillas. Fill with mashed beans, spring onion, cooked chicken, cheddar and coriander, then sandwich together.", "es": "Unta las tortillas con salsa. Rellena con alubias machacadas, cebolleta, pollo cocinado, cheddar y cilantro, y tapa con la otra tortilla."}, {"en": "Brush with oil; fry for about four minutes, turn carefully and cook another two minutes until golden and hot throughout.", "es": "Pincela con aceite y cocina unos cuatro minutos. Da la vuelta con cuidado y cocina otros dos, hasta dorar y calentar todo."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "hot_salsa", "unit": "g"}, {"ingredient_id": "wheat_tortilla", "unit": "g"}, {"ingredient_id": "kidney_beans_canned", "unit": "g"}, {"ingredient_id": "spring_onion", "unit": "g"}, {"ingredient_id": "roast_chicken", "unit": "g"}, {"ingredient_id": "cheddar", "unit": "g"}, {"ingredient_id": "coriander", "unit": "g"}, {"ingredient_id": "vegetable_oil", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_roasted_four_vegetables','{"recipe_id": "global_roasted_four_vegetables", "method": [{"id": "main", "instructions": [{"en": "Heat the oven to 200–220°C. Cut roots evenly and onion into wedges; coat with oil. Start the corn in its husk separately, allowing about 40 minutes.", "es": "Calienta el horno a 200–220°C. Corta los tubérculos uniformemente y la cebolla en gajos; añade aceite. Asa aparte la mazorca con sus hojas, calculando unos 40 minutos."}, {"en": "Roast the roots first for 10–15 minutes, then add onion. Turn occasionally and finish when tender; remove the corn husk before serving.", "es": "Asa los tubérculos 10–15 minutos antes de añadir la cebolla. Remueve y termina cuando estén tiernos; retira las hojas de la mazorca al servir."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "potato", "unit": "g"}, {"ingredient_id": "sweet_potato", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "sweetcorn_raw", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_ramen','{"recipe_id": "global_ramen", "method": [{"id": "main", "instructions": [{"en": "Simmer the stock and water with coriander stalks and most of the chilli for 5–10 minutes.", "es": "Cuece el caldo y el agua con los tallos de cilantro y casi toda la guindilla durante 5–10 minutos."}, {"en": "Add soy sauce, pepper, mushrooms, pak choi, thinly sliced chicken and noodles. Simmer until chicken is cooked through; add bamboo shoots and finish with coriander and chilli.", "es": "Añade soja, pimienta, champiñones, pak choi, pollo en tiras finas y fideos. Cuece hasta cocinar completamente el pollo, añade bambú y termina con cilantro y guindilla."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "chicken_stock", "unit": "g"}, {"ingredient_id": "coriander", "unit": "g"}, {"ingredient_id": "chilli", "unit": "g"}, {"ingredient_id": "soy_sauce", "unit": "g"}, {"ingredient_id": "mushroom", "unit": "g"}, {"ingredient_id": "pak_choi", "unit": "g"}, {"ingredient_id": "chicken", "unit": "g"}, {"ingredient_id": "egg_noodles", "unit": "g"}, {"ingredient_id": "bamboo_shoots", "unit": "g"}, {"ingredient_id": "water", "unit": "g"}, {"ingredient_id": "black_pepper", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_baked_nachos','{"recipe_id": "global_baked_nachos", "method": [{"id": "main", "instructions": [{"en": "Spread chips on an oven tray. Add salsa, sliced spring onion, grated cheddar and chilli flakes.", "es": "Reparte los nachos en una bandeja. Añade salsa, cebolleta cortada, cheddar rallado y copos de guindilla."}, {"en": "Place under the hot oven grill for about three minutes, until the cheese melts.", "es": "Pon bajo el gratinador caliente del horno unos tres minutos, hasta fundir el queso."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "tortilla_chips", "unit": "g"}, {"ingredient_id": "hot_salsa", "unit": "g"}, {"ingredient_id": "spring_onion", "unit": "g"}, {"ingredient_id": "cheddar", "unit": "g"}, {"ingredient_id": "chilli_flakes", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_carrot_muffins','{"recipe_id": "global_carrot_muffins", "method": [{"id": "main", "instructions": [{"en": "Grate carrot and lemon zest. Beat eggs and sweetener for five minutes; mix in oil, milk and yogurt, then flour, baking powder, salt, zest and carrot.", "es": "Ralla zanahoria y limón. Bate huevos y edulcorante cinco minutos; incorpora aceite, leche y yogur, y después harina, levadura, sal, ralladura y zanahoria."}, {"en": "Fill muffin cases and chill 15 minutes while preheating to 250°C. Bake at 200°C without fan for 15–16 minutes, until a skewer comes out clean.", "es": "Llena los moldes y enfría 15 minutos mientras precalientas a 250°C. Hornea a 200°C sin ventilador 15–16 minutos, hasta que la brocheta salga limpia."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "carrot", "unit": "g"}, {"ingredient_id": "lemon_zest", "unit": "g"}, {"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "stevia_sweetener", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "yogurt", "unit": "g"}, {"ingredient_id": "flour", "unit": "g"}, {"ingredient_id": "whole_milk", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}, {"ingredient_id": "baking_powder", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_sweet_potato_cacio','{"recipe_id": "global_sweet_potato_cacio", "method": [{"id": "main", "instructions": [{"en": "Stir-fry the spiralized sweet potato with half the oil for 2–3 minutes. Warm butter, remaining oil and pepper separately, then toss with noodles and both cheeses.", "es": "Saltea el boniato espiralizado con la mitad del aceite 2–3 minutos. Calienta aparte mantequilla, aceite restante y pimienta; mezcla con el boniato y ambos quesos."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "sweet_potato", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}, {"ingredient_id": "butter", "unit": "g"}, {"ingredient_id": "black_pepper", "unit": "g"}, {"ingredient_id": "parmesan", "unit": "g"}, {"ingredient_id": "pecorino", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_creamy_vegan_tomato_pasta','{"recipe_id": "global_creamy_vegan_tomato_pasta", "method": [{"id": "main", "instructions": [{"en": "Soak most cashews in hot water for one hour, drain and blend with water. Cook pasta; toast remaining cashews with oil.", "es": "Remoja casi todos los anacardos una hora en agua caliente, escurre y tritura con agua nueva. Cuece la pasta y tuesta los anacardos restantes con aceite."}, {"en": "Soften onion and garlic, add tomatoes and chilli, cashew cream and pasta water. Finish the pasta in this sauce; add toasted cashews and basil.", "es": "Rehoga cebolla y ajo, añade tomates y guindilla, y después crema de anacardos y agua de pasta. Termina la pasta en la salsa; añade anacardos tostados y albahaca."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "water", "unit": "g"}, {"ingredient_id": "cashew", "unit": "g"}, {"ingredient_id": "pasta", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "chilli_flakes", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "tomato_puree", "unit": "g"}, {"ingredient_id": "sun_dried_tomatoes", "unit": "g"}, {"ingredient_id": "basil", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_sweet_potato_lasagna','{"recipe_id": "global_sweet_potato_lasagna", "method": [{"id": "main", "instructions": [{"en": "Cook onion, garlic and sausage; add tomato sauce and spinach. Mix ricotta, egg, oregano and some Parmesan. Layer with thin sweet potato slices; top with remaining cheeses.", "es": "Cocina cebolla, ajo y salchicha; añade salsa y espinacas. Mezcla ricotta, huevo, orégano y parte del parmesano. Alterna con láminas finas de boniato; cubre con los quesos."}, {"en": "Bake at 190°C, covered for 45 minutes and uncovered for 15. Rest ten minutes; add parsley.", "es": "Hornea a 190°C: 45 minutos tapada y 15 destapada. Reposa diez minutos y añade perejil."}]}], "whole": true, "bases": [], "reason": null, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "italian_sausage", "unit": "g"}, {"ingredient_id": "tomato_sauce", "unit": "g"}, {"ingredient_id": "spinach", "unit": "g"}, {"ingredient_id": "ricotta", "unit": "g"}, {"ingredient_id": "egg", "unit": "g"}, {"ingredient_id": "parmesan", "unit": "g"}, {"ingredient_id": "oregano", "unit": "g"}, {"ingredient_id": "sweet_potato", "unit": "g"}, {"ingredient_id": "mozzarella", "unit": "g"}, {"ingredient_id": "parsley", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}, {"ingredient_id": "black_pepper", "unit": "g"}]}]}'::jsonb);
insert into app_private.cooking_rules values('global_pesto_chicken_gnocchi','{"recipe_id": "global_pesto_chicken_gnocchi", "method": [{"id": "main", "instructions": [{"en": "Brown chicken; soften onion and garlic. Add tomatoes and wine, then stock, cream and gnocchi. Return chicken and bake at 220°C until its centre reaches 75°C.", "es": "Dora el pollo y rehoga cebolla y ajo. Añade tomates, vino, caldo, nata y ñoquis. Reincorpora el pollo y hornea a 220°C hasta alcanzar 75°C en el centro."}, {"en": "Mix in some pesto, add mozzarella and bake four minutes more. Slice chicken and finish with remaining pesto, basil and pine nuts.", "es": "Mezcla parte del pesto, añade mozzarella y hornea cuatro minutos más. Corta el pollo y termina con pesto restante, albahaca y piñones."}]}], "whole": false, "bases": [], "reason": {"en": "Finish at serving time; no reviewed batch preparation.", "es": "Termina al servir; no hay preparación por tandas revisada."}, "ingredients": [{"id": "main", "ingredients": [{"ingredient_id": "chicken", "unit": "g"}, {"ingredient_id": "olive_oil", "unit": "g"}, {"ingredient_id": "onion", "unit": "g"}, {"ingredient_id": "garlic", "unit": "g"}, {"ingredient_id": "tomato", "unit": "g"}, {"ingredient_id": "white_wine", "unit": "g"}, {"ingredient_id": "chicken_stock", "unit": "g"}, {"ingredient_id": "double_cream", "unit": "g"}, {"ingredient_id": "gnocchi", "unit": "g"}, {"ingredient_id": "green_pesto", "unit": "g"}, {"ingredient_id": "mozzarella", "unit": "g"}, {"ingredient_id": "basil", "unit": "g"}, {"ingredient_id": "pine_nuts", "unit": "g"}, {"ingredient_id": "salt", "unit": "g"}, {"ingredient_id": "black_pepper", "unit": "g"}]}]}'::jsonb);
create table app_private.cooking_ledger(household_id uuid primary key references public.household(household_id) on delete cascade, settings jsonb not null,batches jsonb not null default '[]');
create table app_private.cooking_receipts(household_id uuid not null references public.household(household_id) on delete cascade, operation_id uuid not null,actor_id uuid not null,request jsonb not null,created_at timestamptz not null default clock_timestamp(),primary key(household_id,operation_id));
create index cooking_receipts_expiry on app_private.cooking_receipts(created_at);
alter table app_private.cooking_ledger enable row level security;
alter table app_private.cooking_ledger force row level security;
alter table app_private.cooking_receipts enable row level security;
alter table app_private.cooking_receipts force row level security;
create policy cooking_scope on app_private.cooking_ledger to week_menu_executor using(household_id=(select app_private.current_household())) with check(household_id=(select app_private.current_household()));
create policy cooking_receipt_scope on app_private.cooking_receipts to week_menu_executor using(household_id=(select app_private.current_household())) with check(household_id=(select app_private.current_household()));
revoke all on app_private.cooking_ledger,app_private.cooking_receipts from public,anon,authenticated;
grant select,insert,update on app_private.cooking_ledger to week_menu_executor;
grant select,insert,delete on app_private.cooking_receipts to week_menu_executor;
-- JSON numbers with equal values must hash equally after a client round trip (330 and 330.0).
create function app_private.cooking_normalize(value jsonb) returns jsonb language plpgsql immutable set search_path='' as $$begin
 case jsonb_typeof(value)
 when 'number' then return to_jsonb(trim_scale((value#>>'{}')::numeric));
 when 'array' then return (select coalesce(jsonb_agg(app_private.cooking_normalize(v) order by n),'[]') from jsonb_array_elements(value) with ordinality x(v,n));
 when 'object' then return (select coalesce(jsonb_object_agg(k,app_private.cooking_normalize(v)),'{}') from jsonb_each(value) x(k,v));
 else return value;end case;
end$$;
create function app_private.cooking_requirements(settings jsonb) returns jsonb language plpgsql stable set search_path='' as $$
declare result jsonb:='[]'; m record;p jsonb; person record;recipe jsonb;rule jsonb;method jsonb;lines jsonb;selection jsonb;base jsonb; choices jsonb;g numeric; signature text; scope text;rice boolean;begin
 for m in select * from public.meal_plans where day>=current_date-40 order by day,meal_type loop
  for p in select * from jsonb_array_elements(m.data->'portions') loop
   if coalesce((p->>'eating_out')::boolean,false) then continue;end if;
   select x.*,app_private.effective_profile(x.id) as profile into person from public.members x where x.id=(p->>'member_id')::uuid and status='active' and onboarded;
   if not found or person.profile is null then continue;end if;
   select data into recipe from app_private.resolved_saved_recipes where id=p->>'recipe_id' and not archived;
   if not found or exists(select 1 from app_private.recipe_vetoes where recipe_id=p->>'recipe_id' and banned) then continue;end if;
   if exists(select 1 from jsonb_array_elements(p->'lines') l left join app_private.resolved_food_items f on f.id=l->>'ingredient_id' where f.id is null or f.archived or not (f.data->'dietary_patterns' ? (person.profile->>'diet')) or person.profile->'excluded_ingredients' ? (l->>'ingredient_id')) then continue;end if;
   recipe:=coalesce(nullif(p->'recipe_snapshot','null'),recipe);
   select data into rule from app_private.cooking_rules where recipe_id=p->>'recipe_id';if not found then continue;end if;
   select jsonb_agg(jsonb_build_object('id',c->'id','instructions',c->'instructions') order by ord) into method from jsonb_array_elements(recipe->'components') with ordinality x(c,ord);
   if method is distinct from rule->'method' then continue;end if;
   select jsonb_agg(jsonb_build_object('id',c->'id','ingredients',(select jsonb_agg(jsonb_build_object('ingredient_id',i->'ingredient_id','unit',i->'unit') order by n) from jsonb_array_elements(c->'ingredients') with ordinality x(i,n))) order by ord) into method from jsonb_array_elements(recipe->'components') with ordinality x(c,ord);
   if method is distinct from rule->'ingredients' then continue;end if;
   select coalesce(jsonb_agg(l order by ord),'[]') into lines from jsonb_array_elements(p->'lines') with ordinality x(l,ord) where exists(select 1 from jsonb_array_elements(recipe->'components') c where c->>'id'=l->>'component_id' and c->>'kind'<>'dessert');
   choices:='[]';
   for base in select * from jsonb_array_elements(rule->'bases') loop
    select jsonb_agg(l) into selection from jsonb_array_elements(lines) l where l->>'ingredient_id'=base->>'ingredient_id' and l->>'component_id'=base->>'component_id';
    if selection is not null then choices:=choices||jsonb_build_array(jsonb_build_object('scope','base:'||(base->>'ingredient_id')||':plain_boiled','lines',selection,'name',selection->0->'name','kind','base','soak',base->'soak'));end if;
   end loop;
   if (rule->>'whole')::boolean and jsonb_array_length(coalesce(p->'substitutions','[]'))=0 and ((settings->>'prefer_whole')::boolean or jsonb_array_length(choices)=0) then
    choices:=jsonb_build_array(jsonb_build_object('scope','whole','lines',lines,'name',p->'name','kind','recipe','soak',exists(select 1 from jsonb_array_elements(rule->'bases') b where (b->>'soak')::boolean)));
   end if;
   for selection in select * from jsonb_array_elements(choices) loop
    lines:=selection->'lines';scope:=selection->>'scope';
    select sum((l->>'grams')::numeric),bool_or(l->>'ingredient_id' like 'rice_%') into g,rice from jsonb_array_elements(lines) l;
    if g is null or g<=0 then continue;end if;
    select md5(jsonb_build_array(scope,case when scope='whole' then recipe->>'id' else '' end,jsonb_agg(jsonb_build_array(l->'ingredient_id',l->'reference_state',l->'quantity_basis',(l->>'nutrition_revision')::integer,trim_scale((l->>'energy_per_100g')::numeric),trim_scale((l->>'grams')::numeric/gcd((l->>'grams')::numeric,g))::text||'/'||trim_scale(g/gcd((l->>'grams')::numeric,g))::text) order by l->>'ingredient_id',l->>'component_id'))::text) into signature from jsonb_array_elements(lines) l;
    result:=result||jsonb_build_array(selection||jsonb_build_object('id',m.day||'/'||m.meal_type||'/'||person.id||'/'||scope,'day',m.day,'type',m.meal_type,'member_id',person.id,'member',person.name,'recipe_id',recipe->>'id','recipe',p->'name','grams',g,'signature',signature,'menu_signature',md5(app_private.cooking_normalize(lines)::text),'fridge_hours',case when rice then 24 else 48 end,'cool_hours',case when rice then 1 else 2 end,'due_at',((m.day::text||' '||coalesce(person.meal_times->>m.meal_type,case m.meal_type when 'breakfast' then '09:00' when 'lunch' then '14:00' else '21:00' end))::timestamp at time zone (settings->>'timezone')),'instructions',case when scope='whole' then (select jsonb_agg(i) from jsonb_array_elements(recipe->'components') c cross join lateral jsonb_array_elements(c->'instructions') i where c->>'kind'<>'dessert') else '[{"en":"Weigh dry; cook separately according to the packet, cool promptly and divide before storing.","es":"Pesa en seco; cuece aparte según el envase, enfría pronto y reparte antes de guardar."}]'::jsonb end));
   end loop;
  end loop;
 end loop;return result;
end$$;
create function app_private.cooking_audit(h uuid,m uuid,a text,detail jsonb) returns void language plpgsql set search_path='' as $$
declare actor text;begin
 select name into actor from public.members where id=m;
 actor:=coalesce(actor,'Sistema / System');
 insert into app_private.planning_history(household_id,actor_id,actor_name,action,summary,changes)
 values(h,m,actor,case when m is null then 'system' else 'cooking' end,jsonb_build_object('en',actor||': '||(detail->>'en')||'.','es',actor||': '||(detail->>'es')||'.'),jsonb_build_object('cooking',jsonb_build_object('kind','cooking','before',null,'after',detail)));
end$$;
create function app_private.cooking_refresh(batches jsonb,requirements jsonb,settings jsonb) returns jsonb language plpgsql stable set search_path='' as $$
declare output jsonb:='[]'; b jsonb;c jsonb;r jsonb;cs jsonb;changed boolean;pending boolean;begin
 for b in select * from jsonb_array_elements(batches) loop
  cs:='[]';for c in select * from jsonb_array_elements(b->'containers') loop
   select x into r from jsonb_array_elements(requirements) x where x->>'id'=c->>'target_id';
   changed:=c->>'target_id' is not null and (r is null or r->'menu_signature' is distinct from c->'target_snapshot'->'menu_signature' or r->'signature' is distinct from b->'signature' or (c->>'expires_at')::timestamptz<(r->>'due_at')::timestamptz);
   pending:=c->>'status'='reserved' and ((c->'target_snapshot'->>'day')::date+1)::timestamp at time zone coalesce(c->>'usage_timezone',settings->>'timezone')<=clock_timestamp();
   c:=c||jsonb_build_object('review_needed',coalesce(changed,false),'pending',coalesce(pending,false));
   if pending and not changed and c->>'usage_mode'='automatic' then c:=c||'{"status":"assumed","pending":false}';end if;
   cs:=cs||jsonb_build_array(c);
  end loop; output:=output||jsonb_build_array(b||jsonb_build_object('containers',cs));
 end loop;return output;
end$$;
create function app_private.api_get_cooking(h uuid,m uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare l app_private.cooking_ledger%rowtype; req jsonb; fresh jsonb;before_used integer;after_used integer;begin
 perform app_private.assert_context(h,m);perform app_private.actor();
 insert into app_private.cooking_ledger(household_id,settings) values(h,jsonb_build_object('timezone',(select time_zone from public.members where id=m),'sessions','[]'::jsonb,'usage_mode','manual','prefer_whole',false)) on conflict do nothing;
 select * into l from app_private.cooking_ledger where household_id=h for update;
 req:=app_private.cooking_requirements(l.settings);fresh:=app_private.cooking_refresh(l.batches,req,l.settings);
 select count(*) into before_used from jsonb_array_elements(l.batches) b cross join lateral jsonb_array_elements(b->'containers') c where c->>'status'='assumed';
 select count(*) into after_used from jsonb_array_elements(fresh) b cross join lateral jsonb_array_elements(b->'containers') c where c->>'status'='assumed';
 if after_used>before_used then perform app_private.cooking_audit(h,null,'system',jsonb_build_object('en','Automatic consumption of '||(after_used-before_used)||' reserved containers','es','Consumo automático de '||(after_used-before_used)||' recipientes reservados'));perform app_private.bump();end if;
 update app_private.cooking_ledger set batches=fresh where household_id=h;
 return jsonb_build_object('settings',l.settings,'batches',fresh,'requirements',req,'revision',(select revision from public.household_revision where household_id=h and id),'server_now',clock_timestamp());
end$$;
create function app_private.cooking_capacity(batches jsonb,r jsonb,g numeric) returns void language plpgsql immutable set search_path='' as $$
declare covered numeric;begin
 select coalesce(sum((a->>'grams')::numeric),0) into covered from (
  select a from jsonb_array_elements(batches) b cross join lateral jsonb_array_elements(b->'allocations') a where b->>'status'='planned' and a->'target'->>'id'=r->>'id'
  union all select c from jsonb_array_elements(batches) b cross join lateral jsonb_array_elements(b->'containers') c where c->>'status' in ('reserved','used','assumed') and c->>'target_id'=r->>'id'
 ) x;
 if covered+g>(r->>'grams')::numeric+0.000001 then raise exception 'cooking_overallocated';end if;
 if exists(select 1 from (
  select a->'target' as t from jsonb_array_elements(batches) b cross join lateral jsonb_array_elements(b->'allocations') a where b->>'status'='planned'
  union all select c->'target_snapshot' from jsonb_array_elements(batches) b cross join lateral jsonb_array_elements(b->'containers') c where c->>'status' in ('reserved','used','assumed')
 ) x where t->'day'=r->'day' and t->'type'=r->'type' and t->'member_id'=r->'member_id' and t->'scope'<>r->'scope' and (t->>'scope'='whole' or r->>'scope'='whole')) then raise exception 'cooking_review_required';end if;
end$$;
create function app_private.cooking_positive(value jsonb) returns numeric language plpgsql immutable set search_path='' as $$
declare n numeric;begin
 if jsonb_typeof(value) is distinct from 'number' then raise exception 'invalid_cooking_quantity';end if;
 n:=(value#>>'{}')::numeric;if n<=0 or n>1000000 then raise exception 'invalid_cooking_quantity';end if;return n;
end$$;
create function app_private.api_cooking_command(h uuid,m uuid,operation uuid,revision bigint,action text,p jsonb) returns void language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare state jsonb;settings jsonb;batches jsonb;req jsonb;request jsonb;receipt app_private.cooking_receipts%rowtype;task jsonb;b jsonb;c jsonb;r jsonb;first_req jsonb;a jsonb;cs jsonb;allocations jsonb;g numeric;amount numeric;remaining numeric;total numeric;cooked numeric;session timestamptz;at_time timestamptz;stored timestamptz;expires timestamptz;span interval;storage text;ix integer;bi integer;ci integer;found_container boolean:=false;ids jsonb;slot text;previous_slot text;detail jsonb;labels jsonb;begin
 perform app_private.assert_context(h,m);perform app_private.actor();
 if operation is null or action is null or p is null or jsonb_typeof(p)<>'object' then raise exception 'invalid_cooking_command';end if;
 request:=jsonb_build_object('action',action,'payload',p,'revision',revision);
 select * into receipt from app_private.cooking_receipts where household_id=h and operation_id=operation;
 if found then if receipt.actor_id<>m or receipt.request<>request then raise exception 'operation_mismatch';end if;return;end if;
 state:=app_private.api_get_cooking(h,m);
 if (state->>'revision')::bigint is distinct from revision then raise exception 'stale_plan';end if;
 settings:=state->'settings';batches:=state->'batches';req:=state->'requirements';
 if action='settings' then
  settings:=p->'settings';
  if settings is null or jsonb_typeof(settings)<>'object' or not exists(select 1 from pg_timezone_names where name=settings->>'timezone') or coalesce(settings->>'usage_mode','') not in ('manual','automatic') or jsonb_typeof(settings->'prefer_whole') is distinct from 'boolean' or jsonb_typeof(settings->'sessions') is distinct from 'array' then raise exception 'invalid_cooking_settings';end if;
  if jsonb_array_length(settings->'sessions')>14 or (select count(*)<>count(distinct jsonb_build_array(s->'weekday',s->'time')) from jsonb_array_elements(settings->'sessions') s) or exists(select 1 from jsonb_array_elements(settings->'sessions') s where jsonb_typeof(s->'weekday') is distinct from 'number' or coalesce(s->>'weekday','')!~'^[1-7]$' or coalesce(s->>'time','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$') then raise exception 'invalid_cooking_settings';end if;
  -- A new policy only applies to future meals. Past pending reservations keep their policy.
  if settings->'usage_mode' is distinct from state->'settings'->'usage_mode' or settings->'timezone' is distinct from state->'settings'->'timezone' then
   for b,bi in select value,ordinality::integer-1 from jsonb_array_elements(batches) with ordinality loop
    for c,ci in select value,ordinality::integer-1 from jsonb_array_elements(b->'containers') with ordinality loop
     if c->>'status'='reserved' and (c->'target_snapshot'->>'due_at')::timestamptz>clock_timestamp() then batches:=jsonb_set(batches,array[bi::text,'containers',ci::text],c||jsonb_build_object('usage_mode',settings->'usage_mode','usage_timezone',settings->'timezone'));end if;
    end loop;
   end loop;
  end if;
  settings:=settings||jsonb_build_object('mode_since',clock_timestamp());
 elsif action='plan' then
  if jsonb_typeof(p->'tasks') is distinct from 'array' or jsonb_array_length(p->'tasks') not between 1 and 200 then raise exception 'invalid_cooking_command';end if;
  for task in select * from jsonb_array_elements(p->'tasks') loop
   session:=(task->>'session_at')::timestamptz;
   if not isfinite(session) or session<clock_timestamp() or not exists(select 1 from jsonb_array_elements(settings->'sessions') s where (s->>'weekday')::integer=extract(isodow from session at time zone(settings->>'timezone')) and (s->>'time'=to_char(session at time zone(settings->>'timezone'),'HH24:MI') or (((session at time zone(settings->>'timezone'))::date::text||' '||(s->>'time'))::timestamp at time zone(settings->>'timezone'))=session)) then raise exception 'cooking_session_changed';end if;
   if jsonb_typeof(task->'allocations') is distinct from 'array' or jsonb_array_length(task->'allocations')=0 then raise exception 'invalid_cooking_command';end if;
   select x into first_req from jsonb_array_elements(req) x where x->>'id'=task->'allocations'->0->'target'->>'id';if first_req is null then raise exception 'cooking_target_changed';end if;
   allocations:='[]';total:=0;
   for a in select * from jsonb_array_elements(task->'allocations') loop
    select x into r from jsonb_array_elements(req) x where x->>'id'=a->'target'->>'id';
    if r is null or r->'signature'<>first_req->'signature' or r->'menu_signature' is distinct from a->'target'->'menu_signature' then raise exception 'cooking_target_changed';end if;
    g:=app_private.cooking_positive(a->'grams');span:=(r->>'due_at')::timestamptz-session;storage:=a->>'storage';
    if storage is null or storage not in ('fridge','frozen') or span<=interval '0 seconds' or span>interval '30 days' or storage='fridge' and span>make_interval(hours=>(r->>'fridge_hours')::integer) or storage='frozen' and span<interval '24 hours' then raise exception 'cooking_storage_invalid';end if;
    perform app_private.cooking_capacity(batches||jsonb_build_array(jsonb_build_object('status','planned','allocations',allocations,'containers','[]'::jsonb)),r,g);
    allocations:=allocations||jsonb_build_array(jsonb_build_object('target',r,'grams',g,'storage',storage));total:=total+g;
   end loop;
   b:=jsonb_build_object('id',gen_random_uuid(),'status','planned','name',first_req->'name','signature',first_req->'signature','kind',first_req->'kind','scope',first_req->'scope','recipe_id',first_req->'recipe_id','lines',first_req->'lines','grams',total,'planned_grams',total,'cooked_grams',null,'cooked_at',null,'session_at',session,'fridge_hours',first_req->'fridge_hours','cool_hours',first_req->'cool_hours','instructions',first_req->'instructions','soak',first_req->'soak','allocations',allocations,'containers','[]'::jsonb);
   batches:=batches||jsonb_build_array(b);
  end loop;
 elsif action in ('prepare','cancel') then
  select value,ordinality::integer-1 into b,bi from jsonb_array_elements(batches) with ordinality where value->>'id'=p->>'batch_id';
  if b is null or b->>'status'<>'planned' then raise exception 'invalid_cooking_command';end if;
  if action='cancel' then b:=b||'{"status":"discarded"}';
  else
   amount:=app_private.cooking_positive(p->'grams');cooked:=case when p->'cooked_grams' is null or p->'cooked_grams'='null'::jsonb then null else app_private.cooking_positive(p->'cooked_grams') end;
   at_time:=(p->>'cooked_at')::timestamptz;stored:=(p->>'stored_at')::timestamptz;
   if at_time is null or stored is null or not isfinite(at_time) or not isfinite(stored) or stored>clock_timestamp() or at_time>stored or stored-at_time>make_interval(hours=>(b->>'cool_hours')::integer) or clock_timestamp()-at_time>make_interval(hours=>(b->>'fridge_hours')::integer) then raise exception 'cooking_storage_invalid';end if;
   remaining:=amount;cs:='[]';
   -- Demand order is immutable, short batches leave the later demands uncovered.
   for a in select * from jsonb_array_elements(b->'allocations') loop
    select x into r from jsonb_array_elements(req) x where x->>'id'=a->'target'->>'id';
    if r is null or r->'signature'<>b->'signature' or r->'menu_signature'<>a->'target'->'menu_signature' then raise exception 'cooking_review_required';end if;
    g:=least(remaining,(a->>'grams')::numeric);if g<=0 then continue;end if;
    storage:=coalesce(p->'storage_overrides'->>(r->>'id'),a->>'storage');if storage not in ('fridge','frozen') then raise exception 'cooking_storage_invalid';end if;expires:=at_time+make_interval(hours=>case when storage='frozen' then 720 else (b->>'fridge_hours')::integer end);
    if expires<(r->>'due_at')::timestamptz or storage='frozen' and (r->>'due_at')::timestamptz-stored<interval '24 hours' then raise exception 'cooking_storage_invalid';end if;
    cs:=cs||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'batch_id',b->'id','grams',g,'storage',storage,'stored_at',stored,'expires_at',expires,'status','reserved','target_id',r->'id','target_snapshot',r,'usage_mode',settings->'usage_mode','usage_timezone',settings->'timezone'));remaining:=remaining-g;
   end loop;
   if remaining>0 then
    storage:=p->>'storage';if storage is null or storage not in ('fridge','frozen') then raise exception 'cooking_storage_invalid';end if;
    cs:=cs||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'batch_id',b->'id','grams',remaining,'storage',storage,'stored_at',stored,'expires_at',at_time+make_interval(hours=>case when storage='frozen' then 720 else (b->>'fridge_hours')::integer end),'status','available','target_id',null,'target_snapshot',null));
   end if;
   b:=b||jsonb_build_object('status','cooked','grams',amount,'cooked_grams',cooked,'cooked_at',at_time,'containers',cs);
  end if;
  batches:=jsonb_set(batches,array[bi::text],b);
 elsif action='use' then
  ids:=p->'container_ids';
  if jsonb_typeof(ids) is distinct from 'array' or jsonb_array_length(ids)=0 or (select count(*)<>count(distinct x) from jsonb_array_elements(ids) x) then raise exception 'invalid_cooking_command';end if;
  total:=0;
  for b,bi in select value,ordinality::integer-1 from jsonb_array_elements(batches) with ordinality loop
   for c,ci in select value,ordinality::integer-1 from jsonb_array_elements(b->'containers') with ordinality loop
    if not (ids ? (c->>'id')) then continue;end if;
    if c->>'status'<>'reserved' or c->>'storage'<>'fridge' or (c->>'review_needed')::boolean or (c->>'expires_at')::timestamptz<=clock_timestamp() then raise exception 'cooking_review_required';end if;
    slot:=(c->'target_snapshot'->>'day')||'/'||(c->'target_snapshot'->>'type');if previous_slot is not null and previous_slot<>slot then raise exception 'invalid_cooking_command';end if;previous_slot:=slot;
    batches:=jsonb_set(batches,array[bi::text,'containers',ci::text],c||'{"status":"used","pending":false}');total:=total+1;
   end loop;
  end loop;
  if total<>jsonb_array_length(ids) then raise exception 'invalid_cooking_command';end if;
 elsif action in ('assign','release','restore','discard','store') then
  for b,bi in select value,ordinality::integer-1 from jsonb_array_elements(batches) with ordinality loop
   select value,ordinality::integer-1 into c,ci from jsonb_array_elements(b->'containers') with ordinality where value->>'id'=p->>'container_id';if c is null then continue;end if;found_container:=true;
   if action<>'discard' and (c->>'expires_at')::timestamptz<=clock_timestamp() then raise exception 'cooking_expired';end if;
   if action='discard' then
    if c->>'status' not in ('available','reserved') then raise exception 'invalid_cooking_command';end if;c:=c||'{"status":"discarded"}';
   elsif action in ('release','restore') then
    if action='release' and c->>'status'<>'reserved' or action='restore' and c->>'status' not in ('used','assumed') then raise exception 'invalid_cooking_command';end if;
    c:=c||'{"status":"available","target_id":null,"target_snapshot":null,"review_needed":false,"pending":false}';
   elsif action='assign' then
    if c->>'status'<>'available' or c->>'storage'='thawing' then raise exception 'cooking_unavailable_stock';end if;
    select x into r from jsonb_array_elements(req) x where x->>'id'=p->>'target_id';if r is null then raise exception 'cooking_target_changed';end if;
    g:=app_private.cooking_positive(p->'grams');
    if g>(c->>'grams')::numeric+0.000001 or r->'signature'<>b->'signature' or (r->>'due_at')::timestamptz<=clock_timestamp() or (r->>'due_at')::timestamptz>(c->>'expires_at')::timestamptz or c->>'storage'='frozen' and (r->>'due_at')::timestamptz-clock_timestamp()<interval '24 hours' then raise exception 'cooking_storage_invalid';end if;
    perform app_private.cooking_capacity(batches,r,g);
    if g<(c->>'grams')::numeric then b:=jsonb_set(b,'{containers}',(b->'containers')||jsonb_build_array(c||jsonb_build_object('id',gen_random_uuid(),'grams',(c->>'grams')::numeric-g)));end if;
    c:=c||jsonb_build_object('grams',g,'target_id',r->'id','target_snapshot',r,'status','reserved','usage_mode',settings->'usage_mode','usage_timezone',settings->'timezone');
   elsif action='store' then
    if c->>'status' not in ('available','reserved') then raise exception 'invalid_cooking_command';end if;storage:=p->>'storage';
    if c->>'storage'='fridge' and storage='frozen' and c->>'thawed_at' is null then c:=c||jsonb_build_object('storage','frozen','expires_at',(b->>'cooked_at')::timestamptz+interval '30 days');
    elsif c->>'storage'='frozen' and storage='thawing' then c:=c||jsonb_build_object('storage','thawing','thawed_at',clock_timestamp());
    elsif c->>'storage'='thawing' and storage='fridge' then
     expires:=least((c->>'expires_at')::timestamptz,(c->>'thawed_at')::timestamptz+interval '24 hours');
     if expires<=clock_timestamp() then raise exception 'cooking_expired';end if;c:=c||jsonb_build_object('storage','fridge','expires_at',expires);
    else raise exception 'cooking_storage_invalid';end if;
    c:=c||jsonb_build_object('stored_at',clock_timestamp());
   end if;
   b:=jsonb_set(b,array['containers',ci::text],c);batches:=jsonb_set(batches,array[bi::text],b);exit;
  end loop;
  if not found_container then raise exception 'invalid_cooking_command';end if;
 else raise exception 'invalid_cooking_command';end if;
 update app_private.cooking_ledger set settings=settings,batches=batches where household_id=h;
 perform app_private.bump();
 labels:=jsonb_build_object('settings',jsonb_build_object('en','Changed cooking settings','es','Cambió la configuración de cocina'),'plan',jsonb_build_object('en','Planned cooking sessions','es','Planificó sesiones de cocina'),'prepare',jsonb_build_object('en','Registered a cooked batch','es','Registró una tanda cocinada'),'assign',jsonb_build_object('en','Reassigned a container','es','Reasignó un recipiente'),'release',jsonb_build_object('en','Released a reservation','es','Liberó una reserva'),'restore',jsonb_build_object('en','Recorded a leftover','es','Registró un sobrante'),'use',jsonb_build_object('en','Confirmed consumption','es','Confirmó el consumo'),'discard',jsonb_build_object('en','Discarded a container','es','Descartó un recipiente'),'store',jsonb_build_object('en','Changed container storage','es','Cambió la conservación'),'cancel',jsonb_build_object('en','Cancelled a cooking session','es','Canceló una sesión de cocina'));
 detail:=labels->action;
 if action in ('prepare','cancel','assign','release','restore','discard','store') and b is not null and b->'name' is not null then detail:=jsonb_build_object('en',(detail->>'en')||': '||(b->'name'->>'en'),'es',(detail->>'es')||': '||(b->'name'->>'es'));end if;
 if action='plan' then detail:=jsonb_build_object('en','Planned '||jsonb_array_length(p->'tasks')||' cooking preparations','es','Planificó '||jsonb_array_length(p->'tasks')||' preparaciones');
 elsif action='use' then
  select string_agg(distinct (stock.value->'target_snapshot'->>'day')||' · '||(stock.value->'target_snapshot'->>'type'),', ') into slot from jsonb_array_elements(batches) batch_data cross join lateral jsonb_array_elements(batch_data.value->'containers') stock where p->'container_ids' ? (stock.value->>'id');
  detail:=jsonb_build_object('en','Confirmed consumption of '||jsonb_array_length(p->'container_ids')||' containers: '||slot,'es','Confirmó el consumo de '||jsonb_array_length(p->'container_ids')||' recipientes: '||slot);
 end if;
 perform app_private.cooking_audit(h,m,action,detail);
 insert into app_private.cooking_receipts values(h,operation,m,request,clock_timestamp());
end$$;
-- Private helpers cannot be invoked by clients or select arbitrary households.
do $$declare f record;begin
 for f in select oid::regprocedure signature from pg_proc where pronamespace='app_private'::regnamespace and proname in ('cooking_normalize','cooking_requirements','cooking_audit','cooking_refresh','cooking_capacity','cooking_positive','api_get_cooking','api_cooking_command') loop
  execute 'alter function '||f.signature||' owner to week_menu_executor';
  execute 'revoke all on function '||f.signature||' from public,anon,authenticated';
 end loop;
end$$;
grant execute on function app_private.api_get_cooking(uuid,uuid),app_private.api_cooking_command(uuid,uuid,uuid,bigint,text,jsonb) to authenticated;
create function public.get_cooking_state(p_household_id uuid,p_membership_id uuid) returns jsonb language sql set search_path='' as $$select app_private.api_get_cooking(p_household_id,p_membership_id)$$;
create function public.apply_cooking_command(p_household_id uuid,p_membership_id uuid,p_operation uuid,p_revision bigint,p_action text,p_payload jsonb) returns void language sql set search_path='' as $$select app_private.api_cooking_command(p_household_id,p_membership_id,p_operation,p_revision,p_action,p_payload)$$;
revoke all on function public.get_cooking_state(uuid,uuid),public.apply_cooking_command(uuid,uuid,uuid,bigint,text,jsonb) from public,anon;
grant execute on function public.get_cooking_state(uuid,uuid),public.apply_cooking_command(uuid,uuid,uuid,bigint,text,jsonb) to authenticated;
revoke create on schema app_private from week_menu_executor;
create or replace function app_private.purge_planning_history() returns void language plpgsql security definer set search_path='' as $$begin
 delete from app_private.planning_history where created_at<clock_timestamp()-interval '90 days';
 delete from app_private.planning_history_receipts where created_at<clock_timestamp()-interval '90 days';
 delete from app_private.cooking_receipts where created_at<clock_timestamp()-interval '90 days';
end$$;
revoke all on function app_private.purge_planning_history() from public,anon,authenticated,week_menu_executor;
notify pgrst,'reload schema';
commit;
